  if (token.type === "error") {
    return {
      ...parseDiagnostic(
        "PARSE_LEXICAL_ERROR",
        `Unexpected character ${JSON.stringify(token.text)}.`,
        token.span,
      ),
      found: JSON.stringify(token.text),
    };
  }
  return {
    ...parseDiagnostic(
      "PARSE_LEXICAL_ERROR",
      `Token ${tokenDisplay(token)} is not part of this parser's terminal set.`,
      token.span,
    ),
    found: tokenDisplay(token),
  };
